+/**
+ * Variance per item between two days (inclusive): the theoretical use (what
+ * the dishes sold in those days needed), the actual use (every consume
+ * movement) and actual minus theoretical, for items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const byItem = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !batchItem.has(m.batchId)) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const line = byItem.get(batchItem.get(m.batchId)) ?? { theoretical: 0, actual: 0 };
+    line.actual += m.qty;
+    if (m.ref.startsWith("sale:")) line.theoretical += m.qty;
+    byItem.set(batchItem.get(m.batchId), line);
+  }
+  const round = (n) => Math.round(n * 1000) / 1000;
+  return listItems(store)
+    .filter((item) => byItem.has(item.id))
+    .map((item) => {
+      const { theoretical, actual } = byItem.get(item.id);
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: round(theoretical), actual: round(actual), difference: round(actual - theoretical) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
