@@ -0,0 +1,49 @@
+// Sales from the till: each dish sold uses one portion of its recipe. The
+// ledger is the record of a sale: its movements carry the ref
+// `sale:<ticket>` and the time the dish was sold.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** The ledger ref of a till ticket. */
+export function saleRef(ticket) {
+  return `sale:${ticket}`;
+}
+
+/** True when the ledger already holds movements for this ticket. */
+export function ticketImported(store, ticket) {
+  const ref = saleRef(ticket);
+  return store.data.movements.some((m) => m.ref === ref);
+}
+
+/**
+ * Consumes the ingredients of sold dishes; `lines` are { row, ticket, soldAt,
+ * dishId, qty }. All or nothing: when an item runs out, the store is left as
+ * it was and sale_not_enough_stock names the row.
+ */
+export function recordSales(store, lines) {
+  const quantities = store.data.batches.map((b) => [b, b.qty]);
+  const movements = store.data.movements.length;
+  const movementSeq = store.data.seq.movement;
+  try {
+    for (const line of lines) {
+      const dish = (store.data.dishes ?? []).find((d) => d.id === line.dishId);
+      if (!dish) throw new AppError("bad_request", { reason: `row ${line.row}: unknown dish` });
+      try {
+        for (const need of scaled(getRecipe(store, dish.recipeId), line.qty)) {
+          if (need.qty <= 0) continue;
+          consume(store, need.itemId, need.qty, { at: line.soldAt, ref: saleRef(line.ticket) });
+        }
+      } catch (e) {
+        if (e instanceof AppError && e.code === "not_enough_stock")
+          throw new AppError("sale_not_enough_stock", { ...e.params, row: line.row });
+        throw e;
+      }
+    }
+  } catch (e) {
+    for (const [batch, qty] of quantities) batch.qty = qty;
+    store.data.movements.length = movements;
+    store.data.seq.movement = movementSeq;
+    throw e;
+  }
+}
